import json, subprocess, sys
from pathlib import Path
root=Path('/Users/chazu/dev/zig/birnam')
sys.path.insert(0,str(root/'scripts'))
from validation_support import sha
work=Path('/tmp/birnam-slot-string')
baseline=Path('/tmp/birnam-cell-owner/final-prefix')
checks={
    'slots_only': (baseline,work/'slots-only',{'libbirnam_object_model.dylib'}),
    'string_only': (work/'final-prefix',work/'string-only-final',{'libbirnam_object_model.dylib'}),
}
for name,(left,right,expected) in checks.items():
    names={p.name for p in (left/'lib').glob('*.dylib')} & {p.name for p in (right/'lib').glob('*.dylib')}
    different={n for n in names if sha(left/'lib'/n)!=sha(right/'lib'/n)}
    assert different==expected,(name,different)
    for image in (left/'lib').glob('*.image'): assert sha(image)==sha(right/'lib'/image.name)
receipt={'passed':False,'comparisons':{},'ablation':{
    'slots_only':'Standalone-Cell baseline with only candidate ObjectModel dylib substituted; baseline images unchanged.',
    'string_only':'Candidate with only baseline ObjectModel dylib substituted; candidate images unchanged.'}}
for name,first,second,extended in [
    ('combined',baseline,work/'final-prefix',True),
    ('slots_only',baseline,work/'slots-only',False),
    ('string_only',baseline,work/'string-only-final',False),
    ('native_cells_reference',Path('/tmp/birnam-local-defaults/prefix'),work/'final-prefix',False),
]:
    command=[sys.executable,str(root/'scripts/local-cell-bench.py'),str(first),str(second),'--baseline-local']
    if extended: command.append('--extended')
    result=subprocess.run(command,cwd=root,text=True,capture_output=True)
    (work/(name+'-bench.log')).write_text(result.stdout+result.stderr)
    assert result.returncode==0,(name,result.stdout,result.stderr)
    path=Path(result.stdout.strip().split('; ')[-1])
    receipt['comparisons'][name]={'raw_path':str(path),'receipt':json.loads(path.read_text())}
    (work/'measurements.json').write_text(json.dumps(receipt,indent=2)+'\n')
    print(name,json.dumps(receipt['comparisons'][name]['receipt']['summary']),flush=True)
receipt['passed']=True
(work/'measurements.json').write_text(json.dumps(receipt,indent=2)+'\n')

drivers.measure-slots.py:
import sys,json,statistics
from pathlib import Path
root=Path('/Users/chazu/dev/zig/birnam');sys.path.insert(0,str(root/'scripts'))
from validation_support import command,clean_environment,sha
work=Path('/tmp/birnam-slot-string')
exe=root/'.cargo-target/native-message-tests/release/examples/slot_cost'
prefixes={'baseline':Path('/tmp/birnam-cell-owner/final-prefix'),'candidate':work/'final-prefix'}
receipt={'passed':False,'clock':'Darwin owner-thread CPU clock 16','iterations':100000,'runs':[],
 'executable_sha256':sha(exe),'source_sha256':sha(root/'rust/birnam-siphon/examples/slot_cost.rs'),
 'prefixes':{k:str(v) for k,v in prefixes.items()}}
for sample in range(3):
 for label in (('baseline','candidate') if sample%2==0 else ('candidate','baseline')):
  env=clean_environment();env['BIRNAM_TEST_MODULE_DIRECTORY']=str(prefixes[label]/'lib')
  run=command([exe,'100000'],cwd=root,env=env,timeout=180)
  assert run['exit_code']==0 and not run['stderr'],run
  rows=[json.loads(line) for line in run['stdout'].splitlines()]
  assert len(rows)==2 and all(r['iterations']==100000 and r['cpu_ns']>0 for r in rows)
  receipt['runs'].append(dict(sample=sample,label=label,run=run,observations=rows))
  (work/'slot-cost.json').write_text(json.dumps(receipt,indent=2)+'\n')
  print(label,sample,rows,flush=True)
summary={}
for case in ['slot:in:','slot:in:put:']:
 values={label:[r['cpu_ns'] for run in receipt['runs'] if run['label']==label for r in run['observations'] if r['case']==case] for label in prefixes}
 medians={label:statistics.median(v) for label,v in values.items()}
 summary[case]={'cpu_ns':values,'median_cpu_ns':medians,'cpu_reduction_percent':100*(1-medians['candidate']/medians['baseline'])}
receipt.update(passed=True,summary=summary)
(work/'slot-cost.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps(summary),flush=True)
